define({"topics":[{"title":"Replacing the HRMw magnet busbars","shortdesc":"<p class=\"shortdesc\">Remove and install HRMw Z and YX busbars.<\/p>","href":"t_ReplacingTheMagnetBusbars.html","attributes":{"data-id":"id_2004027"},"menu":{"hasChildren":true},"tocID":"id_2004027-d46e245295","next":"id_2004027-d46e245295"},{"title":"Installing the rear endbell","shortdesc":"<p class=\"shortdesc\">Installs the rear endbell onto the magnet.<\/p>","href":"t_InstallingTheRearEndbellParent_2.html","attributes":{"data-id":"id_2003524"},"menu":{"hasChildren":true},"tocID":"id_2003524-d46e246741","next":"id_2003524-d46e246741"},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_64.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e247469","topics":[]},{"title":"Doing DQA calibration","shortdesc":"<p class=\"shortdesc\">The DQA tool determines proper gradient polarity and proper gradient wiring by scanning a series of axial and coronal images of the DQA III phantom.<\/p>","href":"t_UsingtheDQAIICalibrationTool_4.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e247574","topics":[]},{"title":"Doing the EPI White Pixel test (Full mode)","shortdesc":"<p class=\"shortdesc\">This procedure uses echo planar image (EPI) scans and the raw data mode of recon to analyze the raw data for white pixel artifacts. These raw data artifacts can exhibit themselves as corduroy artifacts in images.<\/p>","href":"t_DoingTheEPIWhitePixelTest_FullMode.html","attributes":{"data-id":"id_2001628"},"menu":{"hasChildren":false},"tocID":"id_2001628-d46e247678","topics":[]}]});